    _validators = [
        ("port", lambda v: type(v) is int and not isinstance(v, bool) and 1 <= v <= 65535),
        ("host", lambda v: isinstance(v, str) and len(v) > 0),
        ("workers", lambda v: type(v) is int and not isinstance(v, bool) and v >= 1),
        ("debug", lambda v: isinstance(v, bool)),
    ]

