from __future__ import annotations

from typing import Any

DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def _valid_str(value: Any) -> bool:
    return isinstance(value, str) and len(value) > 0


def _valid_email(value: Any) -> bool:
    return isinstance(value, str) and "@" in value


def _valid_age(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def parse_record(raw: Any) -> dict:
    """Validate and parse a raw record dict.

    Returns a normalised record with an added ``valid`` flag. Returns a
    copy of ``DEFAULT`` when *raw* is ``None``, missing keys, or has
    type / value errors.
    """
    if raw is None:
        return dict(DEFAULT)
    if not isinstance(raw, dict):
        return dict(DEFAULT)
    if not all(key in raw for key in REQUIRED_KEYS):
        return dict(DEFAULT)
    if not isinstance(raw["id"], str):
        return dict(DEFAULT)
    if not _valid_str(raw["name"]):
        return dict(DEFAULT)
    if not _valid_age(raw["age"]):
        return dict(DEFAULT)
    if not _valid_email(raw["email"]):
        return dict(DEFAULT)

    return {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }

