from __future__ import annotations

DEFAULTS = {"port": 8080, "host": "0.0.0.0", "workers": 4, "debug": False}

# (key, type, validator) — all-or-nothing: any bad value → fallback defaults.
_RULES = [
    ("port",  int,   lambda v: 1 <= v <= 65535),
    ("host",  str,   lambda v: len(v) > 0),
    ("workers", int, lambda v: v >= 1),
    ("debug", bool,  lambda v: True),
]


def load_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        return dict(DEFAULTS)

    for key, typ, validator in _RULES:
        if key not in raw:
            continue
        val = raw[key]
        if not isinstance(val, typ) or (typ is int and isinstance(val, bool)) or not validator(val):
            return dict(DEFAULTS)

    return dict(DEFAULTS) | {k: raw[k] for k, _, _ in _RULES if k in raw}

