DEFAULT = {"id": None, "name": "", "age": 0, "email": "", "valid": False}

REQUIRED_KEYS = ("id", "name", "age", "email")


def _has_required_keys(raw: dict) -> bool:
    return all(key in raw for key in REQUIRED_KEYS)


def _validate_id(raw: dict) -> bool:
    return isinstance(raw["id"], str)


def _validate_name(raw: dict) -> bool:
    return isinstance(raw["name"], str) and raw["name"]


def _validate_age(raw: dict) -> bool:
    if isinstance(raw["age"], bool):
        return False
    return isinstance(raw["age"], int) and raw["age"] >= 0


def _validate_email(raw: dict) -> bool:
    return isinstance(raw["email"], str) and "@" in raw["email"]


def _validate(raw: dict) -> bool:
    return (
        _has_required_keys(raw)
        and _validate_id(raw)
        and _validate_name(raw)
        and _validate_age(raw)
        and _validate_email(raw)
    )


def parse_record(raw: object) -> dict:
    if not isinstance(raw, dict) or not _validate(raw):
        return dict(DEFAULT)
    return {
        "id": raw["id"],
        "name": raw["name"],
        "age": raw["age"],
        "email": raw["email"],
        "valid": True,
    }

