_DEFAULT = (None, "", 0, "", False)

REQUIRED_KEYS = ("id", "name", "age", "email")


def _default_record() -> dict:
    return {"id": _DEFAULT[0], "name": _DEFAULT[1], "age": _DEFAULT[2], "email": _DEFAULT[3], "valid": _DEFAULT[4]}


def parse_record(raw: object) -> dict:
    """Parse and validate a raw record dict.

    Returns a validated record with a ``valid`` flag.
    Returns an invalid default record on any validation failure.
    """
    if not isinstance(raw, dict):
        return _default_record()

    if not all(key in raw for key in REQUIRED_KEYS):
        return _default_record()

    if not isinstance(raw["id"], str):
        return _default_record()

    name = raw["name"]
    if not isinstance(name, str) or len(name) == 0:
        return _default_record()

    age = raw["age"]
    if not isinstance(age, int):
        return _default_record()
    if age < 0:
        return _default_record()

    email = raw["email"]
    if not isinstance(email, str) or "@" not in email:
        return _default_record()

    return {
        "id": raw["id"],
        "name": name,
        "age": age,
        "email": email,
        "valid": True,
    }

