from __future__ import annotations


def password_strength(pw: str) -> int:
    score = 0

    if len(pw) >= 8:
        score += 1
    elif len(pw) < 4:
        score -= 1

    has_lower = has_upper = has_digit = has_symbol = False
    for ch in pw:
        if ch.islower():
            has_lower = True
        elif ch.isupper():
            has_upper = True
        elif ch.isdigit():
            has_digit = True
        else:
            has_symbol = True
        if has_lower and has_upper and has_digit and has_symbol:
            break

    score += has_lower + has_upper + has_digit + has_symbol

    repeats = 0
    for i in range(1, len(pw)):
        if pw[i] == pw[i - 1]:
            repeats += 1

    if repeats >= 3:
        score -= 2
    elif repeats >= 1:
        score -= 1

    if len(pw) >= 12 and has_symbol:
        score += 1

    if score < 0:
        score = 0

    return score

