from itertools import groupby


def password_strength(pw: str) -> int:
    score = 0

    if len(pw) >= 8:
        score += 1
    elif len(pw) < 4:
        score -= 1

    has_lower = has_upper = has_digit = has_symbol = False
    for ch in pw:
        if ch.islower():
            has_lower = True
        if ch.isupper():
            has_upper = True
        if ch.isdigit():
            has_digit = True
        if not ch.isalnum():
            has_symbol = True

    if has_lower:
        score += 1
    if has_upper:
        score += 1
    if has_digit:
        score += 1
    if has_symbol:
        score += 1

    repeats = sum(len(list(g)) - 1 for _, g in groupby(pw))

    if repeats >= 3:
        score -= 2
    elif repeats >= 1:
        score -= 1

    if len(pw) >= 12 and has_symbol:
        score += 1

    return max(score, 0)

