from __future__ import annotations


def to_number(text: str) -> float | None:
    """Parse a string into a float.

    Returns the numeric value of *text*, or ``None`` when the input is
    empty, contains non-digit characters (except a leading sign or a
    single decimal point), or has multiple decimal points.

    >>> to_number("  42.0  ")
    42.0
    >>> to_number("-0.5")
    -0.5
    >>> to_number("abc")
    >>> to_number("")
    """
    if not isinstance(text, str):
        return None

    stripped = text.strip()
    if not stripped:
        return None

    body = stripped
    if body.startswith(("+", "-")):
        sign, body = body[0], body[1:]
    else:
        sign = ""

    if not body:
        return None

    dot_count = body.count(".")
    if dot_count > 1:
        return None

    if dot_count:
        whole, _, frac = body.partition(".")
        if not whole or not frac or not whole.isdigit() or not frac.isdigit():
            return None
    elif not body.isdigit():
        return None

    return float(sign + body)

