        score += 1
    if has_digit:
        score += 1
    if has_symbol:
        score += 1

    if repeats >= 3:
        score -= 2
    elif repeats >= 1:
        score -= 1

    if length >= 12 and has_symbol:
        score += 1

    if score < 0:
        score = 0

    return score

