from __future__ import annotations


def password_strength(pw: str) -> int:
    length_score = _length_score(pw)
    flags = _type_flags(pw)
    type_score = sum(flags.values())
    repeat_score = _repeat_score(pw)
    bonus_score = _bonus_score(pw, flags)

    return max(0, length_score + type_score + repeat_score + bonus_score)


def _length_score(pw: str) -> int:
    if len(pw) >= 8:
        return 1
    elif len(pw) < 4:
        return -1
    return 0


def _type_flags(pw: str) -> dict[str, bool]:
    flags = {"lower": False, "upper": False, "digit": False, "symbol": False}

    for ch in pw:
        if ch.islower():
            flags["lower"] = True
        if ch.isupper():
            flags["upper"] = True
        if ch.isdigit():
            flags["digit"] = True
        if not ch.isalnum():
            flags["symbol"] = True

    return flags


def _repeat_score(pw: str) -> int:
    repeats = sum(1 for a, b in zip(pw, pw[1:]) if a == b)
    if repeats >= 3:
        return -2
    elif repeats >= 1:
        return -1
    return 0


def _bonus_score(pw: str, flags: dict[str, bool]) -> int:
    return 1 if len(pw) >= 12 and flags["symbol"] else 0

