def _empty_body(body: str) -> bool:
    return len(body) == 0


def _parse_float(sign: str, body: str) -> float | None:
    if body.count(".") > 1:
        return None

    whole, _, frac = body.partition(".")
    if not whole or not frac:
        return None
    if not whole.isdigit() or not frac.isdigit():
        return None

    return float(sign + body)


def _parse_int(sign: str, body: str) -> float | None:
    if not body.isdigit():
        return None
    return float(sign + body)

