def _valid_int(text: str) -> bool:
    return bool(text) and text.isdigit()


def _valid_float(body: str) -> tuple[str, str] | None:
    whole, _, frac = body.partition(".")
    if not whole or not frac:
        return None
    if not whole.isdigit() or not frac.isdigit():
        return None
    return whole, frac


def _extract_sign(text: str) -> tuple[str, str]:
    if text and text[0] in "+-":
        return text[0], text[1:]
    return "", text


def _valid_body(body: str) -> bool:
    dot_count = body.count(".")
    if dot_count > 1:
        return False
    if dot_count == 1:
        return _valid_float(body) is not None
    return _valid_int(body)


def to_number(text: str) -> float | None:
    if not isinstance(text, str):
        return None
    sign, body = _extract_sign(text.strip())
    if not body:
        return None
    if not _valid_body(body):
        return None
    return float(sign + body)

