from __future__ import annotations


def _length_score(n: int) -> int:
    return 1 if n >= 8 else (-1 if n < 4 else 0)


def _category_score(pw: str) -> tuple[bool, bool, bool, bool]:
    has_lower = has_upper = has_digit = has_symbol = False
    for ch in pw:
        if ch.islower():
            has_lower = True
        elif ch.isupper():
            has_upper = True
        elif ch.isdigit():
            has_digit = True
        else:
            has_symbol = True
    return has_lower, has_upper, has_digit, has_symbol


def _repeat_score(pw: str) -> int:
    repeats = sum(1 for i in range(1, len(pw)) if pw[i] == pw[i - 1])
    return -2 if repeats >= 3 else (-1 if repeats >= 1 else 0)


def _bonus_score(n: int, has_symbol: bool) -> int:
    return 1 if n >= 12 and has_symbol else 0


def password_strength(pw: str) -> int:
    n = len(pw)
    score = _length_score(n)

    has_lower, has_upper, has_digit, has_symbol = _category_score(pw)
    score += sum((has_lower, has_upper, has_digit, has_symbol))

    score += _repeat_score(pw)
    score += _bonus_score(n, has_symbol)

    return max(score, 0)

