from __future__ import annotations


def ticket_price(age: int, day: str, is_member: bool) -> float:
    base = _base_price(age)
    base += _day_surcharge(day)

    if is_member:
        base *= 0.9 if age < 18 else 0.8

    return base


def _base_price(age: int) -> float:
    for threshold, price in [(3, 0.0), (12, 8.0), (18, 12.0), (65, 18.0)]:
        if age < threshold:
            return price
    return 10.0


def _day_surcharge(day: str) -> float:
    if day in ("saturday", "sunday"):
        return 4.0
    if day == "friday":
        return 2.0
    return 0.0

