_AGE_BUCKETS = ((3, 0.0), (12, 8.0), (18, 12.0), (65, 18.0))


def ticket_price(age: int, day: str, is_member: bool) -> float:
    base = next((price for limit, price in _AGE_BUCKETS if age < limit), 10.0)

    if day in ("saturday", "sunday"):
        base += 4.0
    elif day == "friday":
        base += 2.0

    if is_member:
        base *= 0.9 if age < 18 else 0.8

