from __future__ import annotations


def ticket_price(age: int, day: str, is_member: bool) -> float:
    _DAY_SURCHARGE: dict[str, float] = {
        "saturday": 4.0,
        "sunday": 4.0,
        "friday": 2.0,
    }

    _AGE_TIERS: list[tuple[int, float]] = [
        (3, 0.0),
        (12, 8.0),
        (18, 12.0),
        (65, 18.0),
        (float("inf"), 10.0),
    ]

    base = next(
        price for threshold, price in _AGE_TIERS if age < threshold
    )
    base += _DAY_SURCHARGE.get(day.lower(), 0.0)

    if is_member:
        base *= 0.9 if age < 18 else 0.8

    return max(0.0, base)

