  defaultStatus: string;
}

const EVENT_CONFIGS: Record<string, EventConfig> = {
  "user.created":  { field: 'id', wordOrder: 'actionEntity', defaultStatus: 'ok' },
  "user.updated":  { field: 'id', wordOrder: 'actionEntity', defaultStatus: 'ok' },
  "user.deleted":  { field: 'id', wordOrder: 'actionEntity', defaultStatus: 'ok' },
  "order.placed":  { field: 'orderId', wordOrder: 'entityAction', defaultStatus: 'ok' },
  "order.cancelled": { field: 'orderId', wordOrder: 'entityAction', defaultStatus: 'ok' },
  "order.shipped": { field: 'orderId', wordOrder: 'entityAction', defaultStatus: 'ok' },
  "payment.succeeded": { field: 'paymentId', wordOrder: 'entityAction', defaultStatus: 'ok' },
  "payment.failed": { field: 'paymentId', wordOrder: 'entityAction', defaultStatus: 'error' },
  "invoice.issued": { field: 'invoiceId', wordOrder: 'entityAction', defaultStatus: 'ok' },
  "invoice.voided": { field: 'invoiceId', wordOrder: 'entityAction', defaultStatus: 'ok' },
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const config = EVENT_CONFIGS[name];
  if (!config) {
    return { status: "error", message: `unknown event: ${name}` };
  }

  const [entity, action] = name.split('.');
  const id = String(payload.data[config.field] ?? '');
  const body = config.wordOrder === 'entityAction'
    ? `${entity} ${action} ${id}`
    : `${action} ${entity} ${id}`;

  return { status: config.defaultStatus, message: body };
}

