  "payment.succeeded": { status: "ok",   key: "paymentId", entity: "payment" },
  "payment.failed":    { status: "error", key: "paymentId", entity: "payment" },
  "invoice.issued":    { status: "ok",   key: "invoiceId", entity: "invoice" },
  "invoice.voided":    { status: "ok",   key: "invoiceId", entity: "invoice" },
};

const templates: Record<string, (action: string, value: string) => string> = {
  user: (action, value) => `${action} user ${value}`,
  order: (action, value) => `order ${action} ${value}`,
  payment: (action, value) => `payment ${action} ${value}`,
  invoice: (action, value) => `invoice ${action} ${value}`,
};

export function routeEvent(name: string, payload: EventPayload): EventResult {
  const config = handlers[name];
  if (!config) {
    return { status: "error", message: `unknown event: ${name}` };
  }
  const value = String(payload.data[config.key]);
  const verb = name.split(".")[1];
  return {
    status: config.status,
    message: templates[config.entity](verb, value),
  };
}

