export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Readonly<Record<string, string>> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

type FlagHandler = (config: FlagConfig, nextArg: string | undefined) => void;

const FLAGS: Readonly<Record<string, FlagHandler>> = {
  "--verbose": (c) => { c.verbose = true; },
  "--quiet": (c) => { c.quiet = true; },
  "--dry-run": (c) => { c.dryRun = true; },
  "--force": (c) => { c.force = true; },
  "--strict": (c) => { c.strict = true; },
  "--no-color": (c) => { c.color = false; },
  "--output": (c, v) => {
    if (v === undefined) throw new Error("--output requires a path");
    c.outputPath = v;
  },
  "--config": (c, v) => {
    if (v === undefined) throw new Error("--config requires a path");
    c.configPath = v;
  },
  "--format": (c, v) => {
    if (v === undefined || !["json", "yaml", "text"].includes(v)) {
      throw new Error(`unsupported format: ${String(v)}`);
    }
    c.format = v;
  },
  "--log-level": (c, v) => {
    if (v === undefined || !["debug", "info", "warn", "error"].includes(v)) {
      throw new Error(`unsupported log level: ${String(v)}`);
    }
    c.logLevel = v;
  },
  "--retries": (c, v) => {
    const n = Number(v);
    if (!Number.isInteger(n)) throw new Error("--retries must be an integer");
    c.maxRetries = n;
  },
  "--timeout": (c, v) => {
    const n = Number(v);
    if (!Number.isInteger(n)) throw new Error("--timeout must be an integer");
    c.timeoutMs = n;
  },
  "--parallel": (c, v) => {
    const n = Number(v);
    if (!Number.isInteger(n)) throw new Error("--parallel must be an integer");
    c.parallelism = n;
  },
};

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const handler = FLAGS[arg];

    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }

    const isConsuming = !["--verbose", "--quiet", "--dry-run", "--force", "--strict", "--no-color"].includes(arg);
    if (isConsuming) {
      handler(config, argv[++i]);
    } else {
      handler(config, undefined);
    }
  }

  return config;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Readonly<Record<string, string>> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const VALID_FORMATS = new Set(["json", "yaml", "text"]);
const VALID_LOG_LEVELS = new Set(["debug", "info", "warn", "error"]);

type FlagHandler = (config: FlagConfig, argv: string[], i: number) => number;

function makeFlagHandlers(): Readonly<Record<string, FlagHandler>> {
  const setFlag = (key: keyof FlagConfig) => (config: FlagConfig, _argv: string[], i: number) => { config[key] = true; return i; };
  const clearFlag = (key: keyof FlagConfig) => (config: FlagConfig, _argv: string[], i: number) => { config[key] = false; return i; };

  return {
    "--verbose": setFlag("verbose"),
    "--quiet": setFlag("quiet"),
    "--dry-run": setFlag("dryRun"),
    "--force": setFlag("force"),
    "--strict": setFlag("strict"),
    "--no-color": clearFlag("color"),

    "--output": (config: FlagConfig, argv: string[], i: number) => {
      config.outputPath = requireNextArg(argv, i, "output");
      return i;
    },
    "--config": (config: FlagConfig, argv: string[], i: number) => {
      config.configPath = requireNextArg(argv, i, "config");
      return i;
    },
    "--format": (config: FlagConfig, argv: string[], i: number) => {
      const value = requireNextArg(argv, i, "format");
      if (!VALID_FORMATS.has(value)) throw new Error(`unsupported format: ${value}`);
      config.format = value;
      return i;
    },
    "--log-level": (config: FlagConfig, argv: string[], i: number) => {
      const value = requireNextArg(argv, i, "log-level");
      if (!VALID_LOG_LEVELS.has(value)) throw new Error(`unsupported log level: ${value}`);
      config.logLevel = value;
      return i;
    },
    "--retries": (config: FlagConfig, argv: string[], i: number) => {
      const value = Number(argv[++i]!);
      if (!Number.isInteger(value)) throw new Error("--retries must be an integer");
      config.maxRetries = value;
      return i;
    },
    "--timeout": (config: FlagConfig, argv: string[], i: number) => {
      const value = Number(argv[++i]!);
      if (!Number.isInteger(value)) throw new Error("--timeout must be an integer");
      config.timeoutMs = value;
      return i;
    },
    "--parallel": (config: FlagConfig, argv: string[], i: number) => {
      const value = Number(argv[++i]!);
      if (!Number.isInteger(value)) throw new Error("--parallel must be an integer");
      config.parallelism = value;
      return i;
    },
  };
}

function requireNextArg(argv: string[], index: number, flag: string): string {
  const value = argv[++index];
  if (value === undefined) {
    throw new Error(`--${flag} requires a value`);
  }
  return value;
}

const FLAG_HANDLERS = makeFlagHandlers();

function resolveAlias(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = resolveAlias(argv[i]!);
    const handler = FLAG_HANDLERS[arg];
    if (handler === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }
    i = handler(config, argv, i);
  }

  return config;
}

