export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: "json" | "yaml" | "text";
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: "debug" | "info" | "warn" | "error";
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const VALID_FORMATS = new Set(["json", "yaml", "text"]);
const VALID_LOG_LEVELS = new Set(["debug", "info", "warn", "error"]);
const FLAGS_WITH_VALUE = new Set([
  "--output", "--config", "--format", "--log-level",
  "--retries", "--timeout", "--parallel",
]);

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

function applyFlag(config: FlagConfig, flag: string, value: string): void {
  switch (flag) {
    case "--output": config.outputPath = value; break;
    case "--config": config.configPath = value; break;
    case "--format":
      if (!VALID_FORMATS.has(value)) throw new Error(`unsupported format: ${value}`);
      config.format = value; break;
    case "--log-level":
      if (!VALID_LOG_LEVELS.has(value)) throw new Error(`unsupported log level: ${value}`);
      config.logLevel = value; break;
    case "--retries": {
      const n = Number(value);
      if (!Number.isInteger(n)) throw new Error("--retries must be an integer");
      config.maxRetries = n; break;
    }
    case "--timeout": {
      const n = Number(value);
      if (!Number.isInteger(n)) throw new Error("--timeout must be an integer");
      config.timeoutMs = n; break;
    }
    case "--parallel": {
      const n = Number(value);
      if (!Number.isInteger(n)) throw new Error("--parallel must be an integer");
      config.parallelism = n; break;
    }
    // Boolean flags handled inline
  }
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    if (FLAGS_WITH_VALUE.has(arg)) {
      const value = argv[++i];
      if (value === undefined) {
        if (arg === "--output") throw new Error("--output requires a path");
        if (arg === "--config") throw new Error("--config requires a path");
        throw new Error(`${arg} requires a value`);
      }
      applyFlag(config, arg, value);
    } else {
      switch (arg) {
        case "--verbose": config.verbose = true; break;
        case "--quiet": config.quiet = true; break;
        case "--dry-run": config.dryRun = true; break;
        case "--force": config.force = true; break;
        case "--no-color": config.color = false; break;
        case "--strict": config.strict = true; break;
        default: throw new Error(`unknown flag: ${arg}`);
      }
    }
  }

  return config;
}

