export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function requireNext(argv: string[], idx: number, flag: string): string {
  const value = argv[idx + 1];
  if (value === undefined) {
    throw new Error(`${flag} requires a value`);
  }
  return value;
}

function requireInt(argv: string[], idx: number, flag: string): number {
  const raw = requireNext(argv, idx, flag);
  const value = Number(raw);
  if (!Number.isInteger(value)) {
    throw new Error(`${flag} must be an integer`);
  }
  return value;
}

interface FlagHandler {
  handler: (config: FlagConfig, value: string | number) => void;
  consume: (argv: string[], idx: number, flag: string) => string | number;
  conflict?: string[];
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

const VALID_FORMATS = ["json", "yaml", "text"] as const;
const VALID_LOG_LEVELS = ["debug", "info", "warn", "error"] as const;

function isNonNegativeInt(n: number): boolean {
  return Number.isInteger(n) && n >= 0;
}

function isPositiveInt(n: number): boolean {
  return Number.isInteger(n) && n > 0;
}

const stringFlag = (handler: (c: FlagConfig, v: string) => void) =>
  ({ handler: (c, v) => handler(c, v as string), consume: requireNext });

const validatedStringFlag = (
  handler: (c: FlagConfig, v: string) => void,
  validate: (v: string) => boolean,
  errorPrefix: string,
) =>
  ({
    handler: (c, v) => handler(c, v as string),
    consume: (argv, idx, flag) => {
      const v = requireNext(argv, idx, flag);
      if (!validate(v)) throw new Error(`${errorPrefix}: ${v}`);
      return v;
    },
  });

const intFlag = (
  handler: (c: FlagConfig, v: number) => void,
  validate: (v: number) => boolean,
  errorPrefix: string,
) =>
  ({
    handler: (c, v) => handler(c, v as number),
    consume: (argv, idx, flag) => {
      const v = requireInt(argv, idx, flag);
      if (!validate(v)) throw new Error(`${errorPrefix} must be a non-negative integer`);
      return v;
    },
  });

const FLAG_HANDLERS: Record<string, FlagHandler> = {
  "--verbose": { handler: (c) => { c.verbose = true; }, consume: () => true, conflict: ["--quiet"] },
  "--quiet": { handler: (c) => { c.quiet = true; }, consume: () => true, conflict: ["--verbose"] },
  "--dry-run": { handler: (c) => { c.dryRun = true; }, consume: () => false },
  "--force": { handler: (c) => { c.force = true; }, consume: () => false },
  "--no-color": { handler: (c) => { c.color = false; }, consume: () => false },
  "--strict": { handler: (c) => { c.strict = true; }, consume: () => false },
  "--output": stringFlag((c, v) => { c.outputPath = v; }),
  "--config": stringFlag((c, v) => { c.configPath = v; }),
  "--format": validatedStringFlag((c, v) => { c.format = v; }, (v) => VALID_FORMATS.includes(v), "unsupported format"),
  "--log-level": validatedStringFlag((c, v) => { c.logLevel = v; }, (v) => VALID_LOG_LEVELS.includes(v), "unsupported log level"),
  "--retries": intFlag((c, v) => { c.maxRetries = v; }, isNonNegativeInt, "--retries"),
  "--timeout": intFlag((c, v) => { c.timeoutMs = v; }, isPositiveInt, "--timeout"),
  "--parallel": intFlag((c, v) => { c.parallelism = v; }, isPositiveInt, "--parallel"),
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);
    const desc = FLAG_HANDLERS[arg];

    if (desc === undefined) {
      throw new Error(`unknown flag: ${arg}`);
    }

    if (desc.conflict) {
      for (const conflict of desc.conflict) {
        if (config[conflict.slice(2) as keyof FlagConfig] === true) {
          throw new Error(`${arg} conflicts with ${conflict}`);
        }
      }
    }

    const value = desc.consume(argv, i, arg);
    i++;
    desc.handler(config, value);
  }

  return config;
}

