export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

export function gradeReport(record: StudentRecord): GradeReport {
  const baseLetter = computeLetter(record.score);
  const modifier = computeModifier(record);

  const letter = record.absences > 20 ? "F" : baseLetter;
  return { letter, modifier };
}

function computeLetter(score: number): string {
  const grades: [number, string][] = [
    [97, "A+"],
    [93, "A"],
    [90, "A-"],
    [87, "B+"],
    [83, "B"],
    [73, "C"],
    [60, "D"],
    [0,  "F"],
  ];

  for (const [threshold, letter] of grades) {
    if (score >= threshold) return letter;
  }
  return "F";
}

function computeModifier(record: StudentRecord): string {
  if (record.absences > 20) {
    return "attendance-failure";
  }
  if (record.extraCredit >= 5 && record.score >= 90) {
    return "honors";
  }
  return "none";
}

export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const GRADE_SCALE: readonly [number, string][] = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
] as const;

function lookupLetter(score: number): string {
  for (const [threshold, letter] of GRADE_SCALE) {
    if (score >= threshold) return letter;
  }
  return "F";
}

export function gradeReport(record: StudentRecord): GradeReport {
  const letter = lookupLetter(record.score);

  if (record.absences > 20) {
    return { letter: "F", modifier: "attendance-failure" };
  }

  const modifier =
    record.extraCredit >= 5 && record.score >= 90
      ? "honors"
      : "none";

  return { letter, modifier };
}

