    if (handler) {
      const consumesValue = CONSUMES_VALUE.has(arg);
      const value = consumesValue ? argv[++i] : undefined;
      handler(config, value);
    } else {
      throw new Error(`unknown flag: ${arg}`);
    }
  }

  return config;
}

