export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const gradeBoundaries: [number, string][] = [
  [97, "A+"],
  [93, "A"],
  [90, "A-"],
  [87, "B+"],
  [83, "B"],
  [73, "C"],
  [60, "D"],
  [0, "F"],
];

function letterGrade(score: number): string {
  for (const [threshold, letter] of gradeBoundaries) {
    if (score >= threshold) return letter;
  }
  return "F";
}

export function gradeReport(record: StudentRecord): GradeReport {
  if (record.absences > 20) {
    return { letter: "F", modifier: "attendance-failure" };
  }

  const modifier = record.extraCredit >= 5 && record.score >= 90 ? "honors" : "none";

  return { letter: letterGrade(record.score), modifier };
}

