export interface StudentRecord {
  score: number;
  absences: number;
  extraCredit: number;
}

export interface GradeReport {
  letter: string;
  modifier: string;
}

const GRADE_THRESHOLDS: { score: number; letter: string }[] = [
  { score: 97, letter: "A+" },
  { score: 93, letter: "A" },
  { score: 90, letter: "A-" },
  { score: 87, letter: "B+" },
  { score: 83, letter: "B" },
  { score: 73, letter: "C" },
  { score: 60, letter: "D" },
];

function computeLetter(score: number): string {
  let letter = "F";
  for (const t of GRADE_THRESHOLDS) {
    if (score >= t.score) {
      letter = t.letter;
      break;
    }
  }
  return letter;
}

function determineModifier(record: StudentRecord, adjustedScore: number): string {
  if (record.absences > 20) return "attendance-failure";
  if (record.extraCredit >= 5 && adjustedScore >= 90) return "honors";
  return "none";
}

export function gradeReport(record: StudentRecord): GradeReport {
  const adjustedScore = record.score + record.extraCredit;
  const modifier = determineModifier(record, adjustedScore);
  let letter = computeLetter(adjustedScore);
  if (modifier === "attendance-failure") letter = "F";
  return { letter, modifier };
}

