export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

type Handler = (arg: string, config: FlagConfig, value: string | void) => void;

const FLAGS_REQUIRING_VALUE = new Set([
  "--output",
  "--config",
  "--format",
  "--log-level",
  "--retries",
  "--timeout",
  "--parallel",
]);

const parseInteger = (arg: string): number => {
  const value = Number(arg);
  if (!Number.isInteger(value)) {
    throw new Error(`"${arg}" must be an integer`);
  }
  return value;
};

const parseBounded = (arg: string, min: number): number => {
  const value = parseInteger(arg);
  if (value < min) {
    throw new Error(`"${arg}" must be >= ${min}`);
  }
  return value;
};

const handlers: Record<string, Handler> = {
  "--verbose": (_, config) => { config.verbose = true; },
  "--quiet": (_, config) => { config.quiet = true; },
  "--dry-run": (_, config) => { config.dryRun = true; },
  "--force": (_, config) => { config.force = true; },
  "--strict": (_, config) => { config.strict = true; },
  "--no-color": (_, config) => { config.color = false; },
  "--output": (_, config, value) => {
    if (value === undefined) {
      throw new Error("--output requires a path");
    }
    config.outputPath = value;
  },
  "--config": (_, config, value) => {
    if (value === undefined) {
      throw new Error("--config requires a path");
    }
    config.configPath = value;
  },
  "--format": (_, config, value) => {
    if (!["json", "yaml", "text"].includes(value!)) {
      throw new Error(`unsupported format: ${value}`);
    }
    config.format = value!;
  },
  "--log-level": (_, config, value) => {
    if (!["debug", "info", "warn", "error"].includes(value!)) {
      throw new Error(`unsupported log level: ${value}`);
    }
    config.logLevel = value!;
  },
  "--retries": (_, config, value) => { config.maxRetries = parseInteger(value!); },
  "--timeout": (_, config, value) => { config.timeoutMs = parseInteger(value!); },
  "--parallel": (_, config, value) => { config.parallelism = parseInteger(value!); },
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    const handler = handlers[arg];
    if (!handler) {
      throw new Error(`unknown flag: ${arg}`);
    }

    if (FLAGS_REQUIRING_VALUE.has(arg)) {
      const value = argv[++i];
      if (value === undefined) {
        throw new Error(`${arg} requires a path`);
      }
      handler(arg, config, value);
    } else {
      handler(arg, config, undefined);
    }
  }

  return config;
}

