export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function consumeNext(argv: string[], i: number): string | undefined {
  return argv[i + 1];
}

function consumeInt(argv: string[], i: number): number {
  return Number(argv[i + 1]);
}

type Handler = (config: FlagConfig, argv: string[], i: number) => number;

const HANDLERS: Record<string, Handler> = {
  "--verbose": (config) => {
    config.verbose = true;
    return 0;
  },
  "--quiet": (config) => {
    config.quiet = true;
    return 0;
  },
  "--dry-run": (config) => {
    config.dryRun = true;
    return 0;
  },
  "--force": (config) => {
    config.force = true;
    return 0;
  },
  "--no-color": (config) => {
    config.color = false;
    return 0;
  },
  "--strict": (config) => {
    config.strict = true;
    return 0;
  },
  "--output": (config, argv, i) => {
    const v = consumeNext(argv, i);
    if (v === undefined) throw new Error("--output requires a path");
    config.outputPath = v;
    return 1;
  },
  "--config": (config, argv, i) => {
    const v = consumeNext(argv, i);
    if (v === undefined) throw new Error("--config requires a path");
    config.configPath = v;
    return 1;
  },
  "--format": (config, argv, i) => {
    const v = consumeNext(argv, i);
    if (v === undefined || !["json", "yaml", "text"].includes(v)) {
      throw new Error(`unsupported format: ${String(v)}`);
    }
    config.format = v;
    return 1;
  },
  "--log-level": (config, argv, i) => {
    const v = consumeNext(argv, i);
    if (v === undefined || !["debug", "info", "warn", "error"].includes(v)) {
      throw new Error(`unsupported log level: ${String(v)}`);
    }
    config.logLevel = v;
    return 1;
  },
  "--retries": (config, argv, i) => {
    const v = consumeInt(argv, i);
    if (!Number.isInteger(v)) {
      throw new Error("--retries must be an integer");
    }
    config.maxRetries = v;
    return 1;
  },
  "--timeout": (config, argv, i) => {
    const v = consumeInt(argv, i);
    if (!Number.isInteger(v)) {
      throw new Error("--timeout must be an integer");
    }
    config.timeoutMs = v;
    return 1;
  },
  "--parallel": (config, argv, i) => {
    const v = consumeInt(argv, i);
    if (!Number.isInteger(v)) {
      throw new Error("--parallel must be an integer");
    }
    config.parallelism = v;
    return 1;
  },
};

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const raw = argv[i]!;
    const flag = normalizeFlag(raw);
    const handler = HANDLERS[flag];
    if (handler === undefined) {
      throw new Error(`unknown flag: ${raw}`);
    }
    i += handler(config, argv, i);
  }

  return config;
}

