  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const ALLOWED_CURRENCIES = new Set(["USD", "EUR"]);

function validateIdentifiers(order: Order): string[] {
  const errors: string[] = [];
  if (order.id.length === 0) errors.push("order id is required");
  if (order.customerId.length === 0) errors.push("customer id is required");
  return errors;
}

function validateItems(order: Order): string[] {
  const errors: string[] = [];
  if (order.items.length === 0) {
    errors.push("order must contain at least one item");
    return errors;
  }
  for (const item of order.items) {
    if (item.quantity <= 0) {
      errors.push(`item ${item.sku} has a non-positive quantity`);
    }
  }
  return errors;
}

function validateShippingAddress(order: Order): string[] {
  const errors: string[] = [];
  if (order.shippingAddress === null) {
    errors.push("shipping address is required");
  } else if (order.shippingAddress.postalCode.length === 0 || order.shippingAddress.postalCode.trim().length === 0) {
    errors.push("shipping postal code is required");
  }
  return errors;
}

function validateBillingAddress(order: Order): string[] {
  const errors: string[] = [];
  if (order.billingAddress === null) {
    errors.push("billing address is required");
  }
  return errors;
}

function validateTotals(order: Order): string[] {
  const errors: string[] = [];
  if (order.totalCents <= 0) errors.push("order total must be positive");
  if (!ALLOWED_CURRENCIES.has(order.currency)) {
    errors.push(`unsupported currency: ${order.currency}`);
  }
  return errors;
}

export function validateOrder(order: Order): ValidationResult {
  const errors = [
    ...validateIdentifiers(order),
    ...validateItems(order),
    ...validateShippingAddress(order),
    ...validateBillingAddress(order),
    ...validateTotals(order),
  ];

  return { valid: errors.length === 0, errors };
}

export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

