  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const VALID_CURRENCIES = new Set(["USD", "EUR"]);

function validateAddress(addr: Address, label: string, errors: string[]): void {
  if (addr.line1.trim().length === 0) {
    errors.push(`${label} address line 1 is required`);
  }
  if (addr.city.trim().length === 0) {
    errors.push(`${label} city is required`);
  }
  if (addr.postalCode.trim().length === 0) {
    errors.push(`${label} postal code is required`);
  }
}

function validateItems(items: OrderItem[], errors: string[]): void {
  if (items.length === 0) {
    errors.push("order must contain at least one item");
    return;
  }
  for (const item of items) {
    if (item.sku.length === 0) {
      errors.push("item has an empty sku");
    }
    if (item.quantity <= 0) {
      errors.push(`item ${item.sku || "(no sku)"} has a non-positive quantity`);
    }
    if (item.unitPrice < 0) {
      errors.push(`item ${item.sku || "(no sku)"} has a negative unit price`);
    }
  }
}

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [];

  if (order.id.length === 0) {
    errors.push("order id is required");
  }

  if (order.customerId.length === 0) {
    errors.push("customer id is required");
  }

  validateItems(order.items, errors);

  if (order.shippingAddress === null) {
    errors.push("shipping address is required");
  } else {
    validateAddress(order.shippingAddress, "shipping", errors);
  }

  if (order.billingAddress === null) {
    errors.push("billing address is required");
  } else {
    validateAddress(order.billingAddress, "billing", errors);
  }

  if (order.totalCents <= 0) {
    errors.push("order total must be positive");
  }

  if (!VALID_CURRENCIES.has(order.currency)) {
    errors.push(`unsupported currency: ${order.currency}`);
  }

  return { valid: errors.length === 0, errors };
}

