  }
  return errors;
}

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [];

  const idError = validateRequiredId("order", order.id);
  if (idError) errors.push(idError);

  const customerIdError = validateRequiredId("customer", order.customerId);
  if (customerIdError) errors.push(customerIdError);

  errors.push(...validateAddress("shipping", order.shippingAddress));
  errors.push(...validateAddress("billing", order.billingAddress));
  errors.push(...validateItems(order.items));

  if (order.totalCents <= 0) {
    errors.push("order total must be positive");
  }

  if (!VALID_CURRENCIES.has(order.currency)) {
    errors.push(`unsupported currency: ${order.currency}`);
  }

  return { valid: errors.length === 0, errors };
}

