export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  if (raw.maxAttempts !== undefined) {
    const value = Number(raw.maxAttempts);
    if (Number.isInteger(value) && value >= 1 && value <= 10) {
      config.maxAttempts = value;
    }
  } else if (raw.maxAttempts !== undefined && raw.maxAttempts.trim() === "") {
    // empty string → NaN, silently fall back to default
  }

  if (raw.backoffMs !== undefined) {
    const value = Number(raw.backoffMs);
    if (Number.isInteger(value) && value >= 0) {
      config.backoffMs = value;
    }
  } else if (raw.backoffMs !== undefined && raw.backoffMs.trim() === "") {
    // empty string → NaN, silently fall back to default
  }

  if (raw.jitter !== undefined) {
    config.jitter = raw.jitter === "true";
  }

  const ALLOWED_MODES = new Set(["exponential", "linear"]);
  if (raw.mode !== undefined && ALLOWED_MODES.has(raw.mode)) {
    config.mode = raw.mode;
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

type FieldSpec<K extends keyof RetryConfig> = {
  parse: (val: string) => RetryConfig[K] | null;
};

const FIELD_SPECS: { [K in keyof RetryConfig]?: FieldSpec<K> } = {
  maxAttempts: {
    parse(raw: string): number | null {
      const n = Number(raw);
      return Number.isInteger(n) && n >= 1 && n <= 10 ? n : null;
    },
  },
  backoffMs: {
    parse(raw: string): number | null {
      const n = Number(raw);
      return Number.isInteger(n) && n >= 0 ? n : null;
    },
  },
  jitter: {
    parse(raw: string): boolean | null {
      return raw === "true" ? true : raw === "false" ? false : null;
    },
  },
  mode: {
    parse(raw: string): string | null {
      return VALID_MODES.has(raw) ? raw : null;
    },
  },
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const key of Object.keys(FIELD_SPECS) as Array<keyof RetryConfig>) {
    const rawVal = raw[key];
    if (rawVal !== undefined) {
      const spec = FIELD_SPECS[key];
      if (spec) {
        const parsed = spec.parse(rawVal);
        if (parsed !== null) {
          (config as Record<string, unknown>)[key] = parsed;
        }
      }
    }
  }

  return config;
}

