export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
}

export interface Address {
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  shippingAddress: Address | null;
  billingAddress: Address | null;
  totalCents: number;
  currency: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

const VALID_CURRENCIES = new Set(["USD", "EUR"]);

function validateId(id: string, label: string): string | null {
  if (!id || id.trim().length === 0) return `${label.toLowerCase()} is required`;
  return null;
}

function validateAddress(
  address: Address | null,
  label: string
): (string | null)[] {
  if (!address) return [`${label} is required`];
  return [
    !address.postalCode || address.postalCode.trim().length === 0
      ? `${label} postal code is required`
      : null,
  ];
}

function validateItem(item: OrderItem): string[] {
  const errors: string[] = [];
  const hasEmptySku = !item.sku || item.sku.trim().length === 0;
  if (hasEmptySku) errors.push("item has an empty sku");
  if (item.quantity <= 0) {
    errors.push(`item ${item.sku || "<unknown>"} has a non-positive quantity`);
  }
  if (item.unitPrice < 0) {
    errors.push(`item ${item.sku || "<unknown>"} has a negative unit price`);
  }
  return errors;
}

function validateItems(items: OrderItem[]): string[] {
  if (!items || items.length === 0) {
    return ["order must contain at least one item"];
  }
  const errors: string[] = [];
  for (const item of items) {
    errors.push(...validateItem(item));
  }
  return errors;
}

function validateNumericField(value: number, label: string, positive: true): string | null {
  if (!positive || !isFinite(value) || value <= 0) {
    return `${label.toLowerCase()} must be positive`;
  }
  return null;
}

const FIELD_VALIDATORS = [
  (o: Order) => validateId(o.id, "Order"),
  (o: Order) => validateId(o.customerId, "Customer"),
  (o: Order) => validateNumericField(o.totalCents, "Order", true),
  (o: Order) => (!o.currency || !VALID_CURRENCIES.has(o.currency) ? `unsupported currency: ${o.currency || "<missing>"}` : null),
  (o: Order) => validateAddress(o.shippingAddress, "Shipping address"),
  (o: Order) => validateAddress(o.billingAddress, "Billing address"),
] as const;

export function validateOrder(order: Order): ValidationResult {
  const errors: string[] = [
    ...validateItems(order.items),
    ...flatten(
      FIELD_VALIDATORS.map((fn) => {
        const result = fn(order);
        return result === null ? [] : Array.isArray(result) ? result : [result];
      })
    ),
  ];

  return { valid: errors.length === 0, errors };
}

function flatten<T>(nested: (T | T[])[]): T[] {
  const flat: T[] = [];
  for (const item of nested) {
    if (Array.isArray(item)) {
      flat.push(...item);
    } else {
      flat.push(item);
    }
  }
  return flat;
}

