export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  const parse = (
    key: keyof RetryConfig,
    fn: (val: string) => boolean,
    def: number | boolean,
  ) => {
    if (!(key in raw)) return;
    if (fn(raw[key])) (config[key] as number | boolean) = def;
  };

  const parseNum = (
    key: keyof RetryConfig,
    lo: number,
    hi: number | undefined,
    def: number,
  ) => {
    if (!(key in raw)) return;
    const n = Number(raw[key]);
    if (Number.isInteger(n) && n >= lo && (hi === undefined || n <= hi)) {
      config[key] = n;
    }
  };

  parseNum("maxAttempts", 1, 10, 3);
  parseNum("backoffMs", 0, undefined, 200);

  if ("jitter" in raw) {
    if (raw.jitter === "true") config.jitter = true;
    else if (raw.jitter === "false") config.jitter = false;
  }

  if ("mode" in raw && VALID_MODES.has(raw.mode)) {
    config.mode = raw.mode;
  }

  return config;
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

const VALID_MODES = new Set(["exponential", "linear"]);

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  applyNumberField(config, "maxAttempts", raw.maxAttempts, 1, 10);
  applyNumberField(config, "backoffMs", raw.backoffMs, 0, Infinity);
  applyBooleanField(config, "jitter", raw.jitter);
  applyStringField(config, "mode", raw.mode, VALID_MODES);

  return config;
}

function applyNumberField(
  config: RetryConfig,
  key: "maxAttempts" | "backoffMs",
  raw: string | undefined,
  min: number,
  max: number,
): void {
  if (raw === undefined) return;
  const value = Number(raw);
  if (Number.isInteger(value) && value >= min && value <= max) {
    (config as Record<string, unknown>)[key] = value;
  }
}

function applyBooleanField(
  config: RetryConfig,
  key: "jitter",
  raw: string | undefined,
): void {
  if (raw === undefined) return;
  switch (raw) {
    case "true":
      (config as Record<string, unknown>)[key] = true;
      break;
    case "false":
      (config as Record<string, unknown>)[key] = false;
      break;
    default:
      break;
  }
}

function applyStringField(
  config: RetryConfig,
  key: "mode",
  raw: string | undefined,
  allowed: Set<string>,
): void {
  if (raw === undefined) return;
  if (allowed.has(raw)) {
    (config as Record<string, unknown>)[key] = raw;
  }
}

export interface RetryConfig {
  maxAttempts: number;
  backoffMs: number;
  jitter: boolean;
  mode: string;
}

const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  backoffMs: 200,
  jitter: true,
  mode: "exponential",
};

type FieldParser<T> = (value: string) => T | null;

const FIELD_PARSERS: Record<keyof RetryConfig, FieldParser<any>> = {
  maxAttempts: (value) => {
    const n = Number(value);
    return Number.isInteger(n) && n >= 1 && n <= 10 ? n : null;
  },
  backoffMs: (value) => {
    const n = Number(value);
    return Number.isInteger(n) && n >= 0 ? n : null;
  },
  jitter: (value) => (value === "true" ? true : value === "false" ? false : null),
  mode: (value) => (value === "exponential" || value === "linear" ? value : null),
};

export function parseRetryConfig(raw: Record<string, string>): RetryConfig {
  const config: RetryConfig = { ...DEFAULT_RETRY_CONFIG };

  for (const key of Object.keys(FIELD_PARSERS) as (keyof RetryConfig)[]) {
    const value = raw[key];
    if (value !== undefined) {
      const parsed = FIELD_PARSERS[key](value);
      if (parsed !== null) config[key] = parsed;
    }
  }

  return config;
}

