const TIER_BOUNDARIES = [1, 5, 20];

const BASE_COSTS: Record<ShipmentOrder["zone"], number[]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

export function shippingCost(order: ShipmentOrder): number {
  let base = findBase(order.zone, order.weightKg);

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

function findBase(zone: ShipmentOrder["zone"], weightKg: number): number {
  const costs = BASE_COSTS[zone];
  let tier = costs.length - 1;
  for (let i = 0; i < TIER_BOUNDARIES.length; i++) {
    if (weightKg <= TIER_BOUNDARIES[i]) {
      tier = i;
      break;
    }
  }
  return costs[tier];
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const ZONE_COSTS: number[][] = [
  [4, 7, 12, 20],   // domestic
  [9, 15, 25, 40],  // regional
  [18, 30, 55, 55], // international (>20 reuses >5 tier)
];

const ZONE_INDEX = { domestic: 0, regional: 1, international: 2 } as const;

export function shippingCost(order: ShipmentOrder): number {
  const thresholds = [1, 5, 20];
  let tier = 0;
  while (tier < thresholds.length && order.weightKg > thresholds[tier]) {
    tier++;
  }

  const zoneIdx = ZONE_INDEX[order.zone];
  let base = ZONE_COSTS[zoneIdx][tier];

  if (order.priority) base *= 2;
  if (order.fragile && order.weightKg > 5) base += 6;

  return base;
}

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

