  regional:   [9, 15, 25, 40],
  international: [18, 30, 55],
};

const WEIGHT_TIER_CUT = [1, 5, 20];

function pickBase(zone: string, weightKg: number): number {
  const rates = BASE_RATES[zone];
  const tier = WEIGHT_TIER_CUT.findIndex((limit) => weightKg <= limit);
  return rates[tier >= 0 ? tier : rates.length - 1];
}

export function shippingCost(order: ShipmentOrder): number {
  let cost = pickBase(order.zone, order.weightKg);

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

