  regional:  [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

function weightTier(weightKg: number): number {
  if (weightKg <= 1) return 0;
  if (weightKg <= 5) return 1;
  if (weightKg <= 20) return 2;
  return 3;
}

export function shippingCost(order: ShipmentOrder): number {
  let cost = baseCosts[order.zone][weightTier(order.weightKg)];

  if (order.priority) cost *= 2;
  if (order.fragile && order.weightKg > 5) cost += 6;

  return cost;
}

export interface ShipmentOrder {
