  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

const WEIGHT_BRACKETS = [1, 5, 20] as const;

const BASE_COSTS: Record<string, number[]> = {
  domestic:   [4, 7, 12, 20],
  regional:   [9, 15, 25, 40],
  international: [18, 30, 55],
};

export function shippingCost(order: ShipmentOrder): number {
  const costs = BASE_COSTS[order.zone];
  const bracket = bracketIndex(order.weightKg);
  const base = costs[bracket];

  const prioritySurcharge = order.priority ? base : 0;
  const fragileSurcharge = order.fragile && order.weightKg > 5 ? 6 : 0;

  return base + prioritySurcharge + fragileSurcharge;
}

function bracketIndex(weight: number): number {
  for (let i = 0; i < WEIGHT_BRACKETS.length; i++) {
    if (weight <= WEIGHT_BRACKETS[i]) return i;
  }
  return WEIGHT_BRACKETS.length;
}

const TIER_LIMITS = [1, 5, 20] as const;

const BASE_COSTS: Record<string, number[]> = {
  domestic: [4, 7, 12, 20],
  regional: [9, 15, 25, 40],
  international: [18, 30, 55, 55],
};

export interface ShipmentOrder {
  zone: "domestic" | "regional" | "international";
  weightKg: number;
  priority: boolean;
  fragile: boolean;
}

function lookupBaseCost(zone: string, weightKg: number): number {
  const costs = BASE_COSTS[zone];
  for (let i = 0; i < TIER_LIMITS.length; i++) {
    if (weightKg <= TIER_LIMITS[i]) {
      return costs[i];
    }
  }
  return costs[TIER_LIMITS.length];
}

export function shippingCost(order: ShipmentOrder): number {
  let base = lookupBaseCost(order.zone, order.weightKg);

  if (order.priority) {
    base *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    base += 6;
  }

  return base;
}

export interface ShipmentOrder {
