  regional:        [9, 15, 25, 40],
  international:   [18, 30, 55, Infinity],
};

function weightTier(weightKg: number): number {
  if (weightKg <= 1) return 0;
  if (weightKg <= 5) return 1;
  if (weightKg <= 20) return 2;
  return 3;
}

export function shippingCost(order: ShipmentOrder): number {
  let cost: number;

  const tier = weightTier(order.weightKg);
  const costs = BASE_COST[order.zone];

  if (tier === 3 && costs[3] === Infinity) {
    cost = costs[2];
  } else {
    cost = costs[tier];
  }

  if (order.priority) {
    cost *= 2;
  }

  if (order.fragile && order.weightKg > 5) {
    cost += 6;
  }

  return cost;
}

