  const tryStr = (key: "jitter" | "mode", ...valid: string[]): void => {
    const value = raw[key];
    if (value !== undefined && valid.includes(value)) config[key] = value;
  };

  tryNum("maxAttempts", (n) => Number.isInteger(n) && n >= 1 && n <= 10);
  tryNum("backoffMs", (n) => Number.isInteger(n) && n >= 0);

  if (raw.jitter !== undefined && (raw.jitter === "true" || raw.jitter === "false")) {
    config.jitter = raw.jitter === "true";
  }

  tryStr("mode", "exponential", "linear");

  return config;
}
